  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <main id="maincontent">
      <section class="hero" aria-labelledby="page-title">
        <p class="eyebrow">Support</p>
        <h1 id="page-title">Contact our support team</h1>
        <p class="lead">Send us a message and we’ll get back to you as soon as possible.</p>
      </section>

      <section class="panel" aria-labelledby="contact-form-title">
        <h2 id="contact-form-title" class="sr-only" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden;">
          Contact form
        </h2>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            >
            <p id="full-name-error" class="error" hidden></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
            <input
              id="email-address"
              name="email"
              type="email"
              autocomplete="email"
              required
              aria-describedby="email-address-error"
            >
            <p id="email-address-error" class="error" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number</label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              aria-describedby="phone-number-help"
            >
            <p id="phone-number-help" class="help">Use a format like +1 555 123 4567, including a country code if needed.</p>
          </div>

          <p id="form-status" class="status" aria-live="polite"></p>

          <div class="actions">
            <button type="submit">Send message</button>
            <p class="fine-print">Fields marked with <span aria-hidden="true">*</span> are required.</p>
          </div>
        </form>
      </section>
