        helpText = '',
        errorText = '',
        describedBy = ''
      }) => `
        <div class="form-field">
          <label for="${id}">${label}${required ? ' <span class="required" aria-hidden="true">*</span>' : ''}</label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            autocomplete="${autocomplete}"
            ${required ? 'required' : ''}
            ${describedBy ? `aria-describedby="${describedBy}"` : ''}
