          ${helpText ? `<p id="${id}-help" class="help">${helpText}</p>` : ''}
          ${errorText ? `<p id="${id}-error" class="error" hidden></p>` : ''}
        </div>
      `;

      const supportForm = () => `
        <main id="maincontent">
          <section class="hero" aria-labelledby="page-title">
            <p class="eyebrow">Support</p>
            <h1 id="page-title">Contact our support team</h1>
            <p class="lead">Send us a message and we’ll get back to you as soon as possible.</p>
          </section>

          <section class="panel" aria-labelledby="contact-form-title">
            <h2 id="contact-form-title" class="sr-only" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden;">
              Contact form
            </h2>

            <form id="support-form" novalidate>
              ${field({
                id: 'full-name',
                label: 'Full name',
                name: 'fullName',
                type: 'text',
                autocomplete: 'name',
                required: true,
                errorText: 'Error: Enter your full name.'
              })}

              ${field({
                id: 'email-address',
                label: 'Email address',
                name: 'email',
                type: 'email',
                autocomplete: 'email',
                required: true,
                errorText: 'Error: Enter a valid email address.'
              })}

              ${field({
                id: 'phone-number',
                label: 'Phone number',
                name: 'phone',
                type: 'tel',
                autocomplete: 'tel',
                helpText: 'Use a format like +1 555 123 4567, including a country code if needed.',
                describedBy: 'phone-number-help'
              })}

              <p id="form-status" class="status" aria-live="polite"></p>

              <div class="actions">
                <button type="submit">Send message</button>
                <p class="fine-print">Fields marked with <span aria-hidden="true">*</span> are required.</p>
              </div>
            </form>
          </section>
        </main>
      `;

      app.innerHTML = supportForm();

      const form = document.getElementById('support-form');
      const status = document.getElementById('form-status');

      const fields = [
        {
          input: document.getElementById('full-name'),
          error: document.getElementById('full-name-error'),
          message: 'Error: Enter your full name.'
        },
        {
          input: document.getElementById('email-address'),
          error: document.getElementById('email-address-error'),
          message: 'Error: Enter a valid email address.'
        }
      ];

      function setFieldError(field, message) {
        field.input.setAttribute('aria-invalid', 'true');
        field.error.textContent = message;
        field.error.hidden = false;
      }

      function clearFieldError(field) {
        field.input.removeAttribute('aria-invalid');
        field.error.textContent = '';
        field.error.hidden = true;
      }

      function validateField(field) {
        if (field.input.validity.valid) {
          clearFieldError(field);
          return true;
        }

        setFieldError(field, field.message);
        return false;
      }

      fields.forEach((field) => {
        field.input.addEventListener('input', () => {
          if (field.input.value.trim() !== '' || field.input.validity.valid) {
            validateField(field);
          } else {
            clearFieldError(field);
          }
        });

        field.input.addEventListener('blur', () => {
          if (field.input.value.trim() !== '') {
            validateField(field);
          }
        });
      });

      form.addEventListener('submit', (event) => {
        event.preventDefault();

        status.textContent = '';

        const invalidField = fields.find((field) => !validateField(field));

        if (invalidField) {
          invalidField.input.focus();
          return;
        }

        status.textContent = 'Thanks — your message is ready to send.';
        form.reset();
        fields.forEach(clearFieldError);
      });
    </script>
